class BST {
    Node root;
    void insert(int key) {
        root = insertRec(root, key);
    }
    Node insertRec(Node root, int key) {
        if (root == null) return new Node(key);
        if (key < root.data) root.left = insertRec(root.left, key);
        else if (key > root.data) root.right = insertRec(root.right, key);
        return root;
    }

    boolean search(Node root, int key) {
        if (root == null) return false;
        if (root.data == key) return true;
        return key < root.data ? search(root.left, key) :
            search(root.right, key);
    }
    public static void main(String[] args) {
        BST tree = new BST();
        tree.insert(50);
        tree.insert(30);
        tree.insert(70);
        System.out.println("Search 30: " + tree.search(tree.root, 30));
        System.out.println("Search 90: " + tree.search(tree.root,
            90));
    }
}

class AVLNode {
    int data, height;
    AVLNode left, right;
    AVLNode(int value) { data = value; height = 1; }
}

class AVLTree {
    AVLNode rightRotate(AVLNode y) {
        AVLNode x = y.left;
        AVLNode T2 = x.right;
        // Perform rotation
        x.right = y;
        y.left = T2;
        // Update heights
        y.height = Math.max(height(y.left), height(y.right)) + 1;
        x.height = Math.max(height(x.left), height(x.right)) + 1;
        return x; // new root
    }
    int height(AVLNode n) { return n == null ? 0 : n.height; }
}

import java.util.PriorityQueue;
public class HeapExample {
    public static void main(String[] args) {
        // Java's PriorityQueue is a Min-Heap by default
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        minHeap.add(20);
        minHeap.add(5);
        minHeap.add(15);
        System.out.println("Min element: " + minHeap.peek()); // 5
        System.out.println("Extract min: " + minHeap.poll()); // 5
        System.out.println("Next min: " + minHeap.peek());    // 15
    }
}

