public class GraphMatrix {
    private int[][] matrix;
    private int vertices;
    public GraphMatrix(int vertices) {
        this.vertices = vertices;
        matrix = new int[vertices][vertices];
    }
    // Add edge (undirected)
    public void addEdge(int i, int j) {
        matrix[i][j] = 1;
        matrix[j][i] = 1;
    }

    // Print adjacency matrix
    public void printMatrix() {
        for (int i = 0; i < vertices; i++) {
            for (int j = 0; j < vertices; j++) {
                System.out.print(matrix[i][j] + " ");
            }
            System.out.println();
        }
    }

    public static void main(String[] args) {
        GraphMatrix g = new GraphMatrix(4);
        g.addEdge(0, 1);
        g.addEdge(0, 2);
        g.addEdge(1, 2);
        g.addEdge(2, 3);
        g.printMatrix();
    }
}

import java.util.*;
public class GraphList {
    private List<List<Integer>> adjList;
    private int vertices;
    public GraphList(int vertices) {
        this.vertices = vertices;
        adjList = new ArrayList<>();
        for (int i = 0; i < vertices; i++) {
            adjList.add(new ArrayList<>());
        }
    }

    // Add edge (undirected)
    public void addEdge(int i, int j) {
        adjList.get(i).add(j);
        adjList.get(j).add(i);
    }
    // Print adjacency list
    public void printList() {
        for (int i = 0; i < vertices; i++) {
            System.out.print(i + ": ");
            for (int neighbor : adjList.get(i)) {
                System.out.print(neighbor + " ");
            }
            System.out.println();
        }
    }

    public static void main(String[] args) {
        GraphList g = new GraphList(4);
        g.addEdge(0, 1);
        g.addEdge(0, 2);
        g.addEdge(1, 2);
        g.addEdge(2, 3);
        g.printList();
    }
}

import java.util.*;
public class DFSEdgeList {
    private List<int[]> edges;   // store edges as pairs
    private boolean[] visited;
    private int vertices;
    public DFSEdgeList(int vertices) {
        this.vertices = vertices;
        edges = new ArrayList<>();
        visited = new boolean[vertices];
    }

    // Add edge (undirected)
    public void addEdge(int u, int v) {
        edges.add(new int[]{u, v});
        edges.add(new int[]{v, u}); // store both directions
    }
    // Get neighbors of a vertex by scanning edge list
    private List<Integer> getNeighbors(int v) {
        List<Integer> neighbors = new ArrayList<>();
        for (int[] edge : edges) {
            if (edge[0] == v) {
                neighbors.add(edge[1]);
            }
        }
        return neighbors;
    }

    // Recursive DFS
    public void dfs(int v) {
        visited[v] = true;
        System.out.print(v + " ");
        for (int neighbor : getNeighbors(v)) {
            if (!visited[neighbor]) {
                dfs(neighbor);
            }
        }
    }

    public static void main(String[] args) {
        DFSEdgeList g = new DFSEdgeList(5);
        // Build sample graph
        g.addEdge(0, 1);
        g.addEdge(0, 2);
        g.addEdge(1, 3);
        g.addEdge(1, 4);
        System.out.println("DFS starting at node 0:");
        g.dfs(0);
    }
}

import java.util.*;
public class BFSEdgeList {
    private List<int[]> edges;   // store edges as pairs
    private boolean[] visited;
    private int vertices;
    public BFSEdgeList(int vertices) {
        this.vertices = vertices;
        edges = new ArrayList<>();
        visited = new boolean[vertices];
    }

    // Add edge (undirected)
    public void addEdge(int u, int v) {
        edges.add(new int[]{u, v});
        edges.add(new int[]{v, u}); // store both directions
    }
    // Get neighbors of a vertex by scanning edge list
    private List<Integer> getNeighbors(int v) {
        List<Integer> neighbors = new ArrayList<>();
        for (int[] edge : edges) {
            if (edge[0] == v) {
                neighbors.add(edge[1]);
            }
        }
        return neighbors;
    }

    public void bfs(int start) { // BFS using a queue
        Queue<Integer> queue = new LinkedList<>();
        visited[start] = true;
        queue.add(start);
        while (!queue.isEmpty()) {
            int v = queue.poll();
            System.out.print(v + " ");
            for (int neighbor : getNeighbors(v)) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.add(neighbor);
                }
            }
        }
    }

    public static void main(String[] args) {
        BFSEdgeList g = new BFSEdgeList(5);
        // Build sample graph
        g.addEdge(0, 1);
        g.addEdge(0, 2);
        g.addEdge(1, 3);
        g.addEdge(1, 4);
        System.out.println("BFS starting at node 0:");
        g.bfs(0);
    }
}
